begin;
create schema subtitle_test;
create table subtitle_test.results(name text,passed boolean);
grant usage on schema subtitle_test to anon,authenticated,service_role;
create function subtitle_test.assert(name text,ok boolean) returns void language plpgsql security definer as $$ begin
 if ok is distinct from true then raise exception 'ASSERTION FAILED: %',name;end if;
 insert into subtitle_test.results values(name,true);end $$;
create function subtitle_test.denied(name text,command text,expected text) returns void language plpgsql security invoker as $$ begin
 begin execute command;exception when others then
 if sqlerrm=expected then perform subtitle_test.assert(name,true);return;end if;raise;end;
 raise exception 'ASSERTION FAILED: % (allowed)',name;end $$;
insert into auth.users(id,email_confirmed_at) values('aa000000-0000-4000-8000-000000000001',now()),('aa000000-0000-4000-8000-000000000002',now());
insert into private.admin_owners(user_id) values('aa000000-0000-4000-8000-000000000001');
insert into public.movies(id,tmdb_id,title,original_title) values('aa100000-0000-4000-8000-000000000001',9532,'Analysis fixture','Analysis fixture');
select subtitle_test.assert('raw queue and worker methods are not available to public users',not has_table_privilege('authenticated','private.subtitle_jobs','SELECT') and not has_function_privilege('authenticated','public.claim_subtitle_job()','EXECUTE'));
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select subtitle_test.denied('non-owner cannot queue subtitles',$q$select public.admin_subtitle_action('enqueue','aa100000-0000-4000-8000-000000000001',null,null,null,false,null)$q$,'FORBIDDEN');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000001',true);
select public.admin_subtitle_action('enqueue','aa100000-0000-4000-8000-000000000001',null,null,null,false,null);
select public.admin_subtitle_action('enqueue','aa100000-0000-4000-8000-000000000001',null,null,null,false,null);
select subtitle_test.assert('repeated requests reuse one job',jsonb_array_length(public.get_admin_subtitle_jobs(null)->'jobs')=1);
select subtitle_test.assert('search includes existing job details for review',jsonb_array_length(public.get_admin_subtitle_jobs('Analysis fixture')->'jobs')=1 and public.get_admin_subtitle_jobs('Analysis fixture')->'jobs'->0->>'state'='queued');
select subtitle_test.assert('search filters jobs as well as movies',jsonb_array_length(public.get_admin_subtitle_jobs('Unrelated title')->'jobs')=0);
reset role;
create table subtitle_test.claim(value jsonb);
grant select,insert on subtitle_test.claim to service_role;
set local role service_role;
insert into subtitle_test.claim select public.claim_subtitle_job();
select subtitle_test.assert('claim gets correct movie',(select value->>'tmdbId'='9532' from subtitle_test.claim));
select subtitle_test.assert('only one worker can hold a live lease',public.claim_subtitle_job() is null);
select subtitle_test.denied('wrong lease cannot complete',$q$select public.finish_subtitle_job((select (value->>'id')::uuid from subtitle_test.claim),'00000000-0000-4000-8000-000000000000',null,'provider_error')$q$,'REVISION_CONFLICT');
reset role;
select subtitle_test.denied('service credential cannot skip the queue through raw table access',$q$set local role service_role; select * from private.subtitle_jobs$q$,'permission denied for table subtitle_jobs');
select subtitle_test.denied('result cannot contain raw subtitle text',$q$select public.finish_subtitle_job((select (value->>'id')::uuid from subtitle_test.claim),(select (value->>'leaseToken')::uuid from subtitle_test.claim),'{"rating":3,"verdict":"x","factors":{},"rulesVersion":"v1","scorerVersion":"v1","subtitleLanguage":"EN","subtitleHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","cueCount":100,"subtitleText":"private"}'::jsonb,null)$q$,'INVALID_REQUEST');
select public.finish_subtitle_job((select (value->>'id')::uuid from subtitle_test.claim),(select (value->>'leaseToken')::uuid from subtitle_test.claim),'{"rating":3,"verdict":"test","factors":{"mildProfanityCues":1,"strongProfanityCues":8,"slurCues":0,"sexualContentCues":0,"sexualViolenceReferenceCues":0},"rulesVersion":"v2","scorerVersion":"v1","subtitleLanguage":"EN","subtitleHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","cueCount":100}'::jsonb,null);
select subtitle_test.assert('unapproved result is invisible',public.get_subtitle_estimate('aa100000-0000-4000-8000-000000000001') is null);
set local role authenticated;
select subtitle_test.denied('approval needs watched confirmation',$q$select public.admin_subtitle_action('approve',null,(public.get_admin_subtitle_jobs(null)->'jobs'->0->>'id')::uuid,3,3,false,null)$q$,'WATCH_CONFIRMATION_REQUIRED');
select subtitle_test.denied('overriding score requires reason',$q$select public.admin_subtitle_action('approve',null,(public.get_admin_subtitle_jobs(null)->'jobs'->0->>'id')::uuid,3,4,true,null)$q$,'INVALID_REQUEST');
select public.admin_subtitle_action('approve',null,(public.get_admin_subtitle_jobs(null)->'jobs'->0->>'id')::uuid,3,3,true,null);
select subtitle_test.assert('approved estimate published',public.get_subtitle_estimate('aa100000-0000-4000-8000-000000000001')->>'rating'='3');
select subtitle_test.denied('stale second decision cannot overwrite',$q$select public.admin_subtitle_action('reject',null,(public.get_admin_subtitle_jobs(null)->'jobs'->0->>'id')::uuid,3,null,false,'Disagree')$q$,'REVISION_CONFLICT');
select subtitle_test.assert('public projection contains no hashes or reviewer identity',public.get_subtitle_estimate('aa100000-0000-4000-8000-000000000001')::text not like '%Hash%' and public.get_subtitle_estimate('aa100000-0000-4000-8000-000000000001')::text not like '%aa000000%');
select public.admin_subtitle_action('reopen',null,(public.get_admin_subtitle_jobs(null)->'jobs'->0->>'id')::uuid,4,null,false,'Wrong cut, recheck');
select subtitle_test.assert('reopening withdraws public estimate',public.get_subtitle_estimate('aa100000-0000-4000-8000-000000000001') is null);
reset role;
select subtitle_test.assert('review decisions have audit history',(select count(*)=3 from private.subtitle_review_events));
select subtitle_test.assert('audit records the resulting revision',(select max(revision)=5 from private.subtitle_review_events));
select subtitle_test.assert('community votes remain untouched',(select count(*)=0 from public.contributions where movie_id='aa100000-0000-4000-8000-000000000001'));
select name,passed from subtitle_test.results;
rollback;
